import{_ as t,o as l,c as n,a2 as i}from"./chunks/framework.CZqXuAiL.js";const h=JSON.parse('{"title":"Installation","description":"Install Blue Plugin Installer on a Pterodactyl panel via Blueprint or the standalone manual path.","frontmatter":{"title":"Installation","description":"Install Blue Plugin Installer on a Pterodactyl panel via Blueprint or the standalone manual path."},"headers":[],"relativePath":"blue-plugin-installer/getting-started/installation.md","filePath":"blue-plugin-installer/getting-started/installation.md","lastUpdated":1785522590000}'),a={name:"blue-plugin-installer/getting-started/installation.md"};function o(s,e,r,d,c,p){return l(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Blue Plugin Installer installs on any Blueprint-enabled Pterodactyl panel. Two distributions are available in every release zip (<code>blue-plugin-installer-vX.Y.Z.zip</code>):</p><ul><li><code>blueprint/</code> — the <code>.blueprint</code> package, installed with the Blueprint CLI (<strong>recommended</strong>)</li><li><code>standalone/</code> — all extension files plus a manual-installation guide (for panels where the CLI can&#39;t run)</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Pterodactyl Panel <strong>1.11.x – 1.14.x</strong> (tested on <strong>1.14.1</strong>)</li><li>Blueprint framework <code>beta-2026-01</code>, <code>beta-2026-02</code>, <code>beta-2026-05</code>, or <code>beta-2026-06</code></li><li>Root or sudo SSH access to the panel server</li><li>Outbound HTTPS from the panel to <code>api.modrinth.com</code>, <code>api.curseforge.com</code>, <code>hangar.papermc.io</code>, <code>api.spiget.org</code>, and <code>api.polymart.org</code></li><li>A <strong>CurseForge API key</strong> — only if you want CurseForge results. Create one at <a href="https://console.curseforge.com/" target="_blank" rel="noreferrer">https://console.curseforge.com/</a>; the other providers work without any key.</li></ul><h2 id="blueprint-install-recommended" tabindex="-1">Blueprint install (recommended) <a class="header-anchor" href="#blueprint-install-recommended" aria-label="Permalink to &quot;Blueprint install (recommended)&quot;">​</a></h2><ol><li><p>Download <code>blueplugininstaller-vX.Y.Z.blueprint</code> from the <a href="https://github.com/AnAverageBeing/blue-plugin-installer/releases" target="_blank" rel="noreferrer">latest release</a>.</p></li><li><p>Copy it into your panel directory and run the installer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueplugininstaller-vX.Y.Z.blueprint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl/</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueplugininstaller-vX.Y.Z</span></span></code></pre></div></li><li><p>Wait for Blueprint to finish — it rebuilds the panel frontend (<code>yarn build:production</code>), which can take a few minutes.</p></li></ol><h2 id="standalone-manual-install" tabindex="-1">Standalone (manual) install <a class="header-anchor" href="#standalone-manual-install" aria-label="Permalink to &quot;Standalone (manual) install&quot;">​</a></h2><p>If <code>blueprint -install</code> fails or you want to audit every change, follow <code>standalone/INSTALLATION.md</code> inside the release zip. In short, you will:</p><ol><li>Replace the <code>{identifier}</code> / <code>{version}</code> / <code>{author}</code> placeholders in all files.</li><li>Copy <code>controllers/</code> to <code>.blueprint/extensions/blueplugininstaller/app/</code> and symlink it to <code>app/BlueprintFramework/Extensions/blueplugininstaller</code>.</li><li>Copy <code>routes.php</code> to <code>.blueprint/extensions/blueplugininstaller/routers/client.php</code> and symlink it to <code>routes/blueprint/client/blueplugininstaller.php</code>.</li><li>Copy <code>controller.php</code> (renamed to <code>blueplugininstallerExtensionController.php</code>) and <code>view.blade.php</code> into the admin controller/view locations.</li><li>Register the extension (<code>.store/conf.yml</code>, <code>.store/Components.yml</code>, <code>installed_extensions</code>).</li><li>Copy <code>components/</code> and symlink it to <code>resources/scripts/blueprint/extensions/blueplugininstaller</code>, then add the navigation route to <code>resources/scripts/blueprint/extends/routers/routes.ts</code>.</li><li>Rebuild the frontend (<code>yarn build:production</code> as the web user) and clear caches.</li></ol><div class="warning custom-block"><p class="custom-block-title">The Blueprint framework is still required</p><p>&quot;Standalone&quot; replaces the <strong>CLI</strong>, not the framework — the controllers call <code>BlueprintAdminLibrary</code> and the components import through the <code>@/blueprint/extensions/*</code> webpack alias.</p></div><h2 id="post-install-verification" tabindex="-1">Post-install verification <a class="header-anchor" href="#post-install-verification" aria-label="Permalink to &quot;Post-install verification&quot;">​</a></h2><ul><li><strong>Admin area</strong>: open <strong>Admin → Extensions → Blue Plugin Installer</strong> (<code>/admin/extensions/blueplugininstaller</code>) and set the CurseForge API key.</li><li><strong>Server area</strong>: open any Minecraft server — a <strong>Plugin Installer</strong> tab appears in the sidebar (<code>/server/&lt;id&gt;/blueplugininstaller</code>).</li><li><strong>Smoke test</strong>: search for any plugin on Modrinth (no key needed). If results render, the extension is fully wired.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>Sidebar tab missing after install</td><td>The frontend rebuild didn&#39;t finish. Run <code>sudo -u www-data yarn install &amp;&amp; sudo -u www-data yarn build:production</code> in the panel dir (on Node ≥ 17 export <code>NODE_OPTIONS=--openssl-legacy-provider</code> first).</td></tr><tr><td>CurseForge errors / empty results</td><td>The API key in the admin settings is missing or invalid. Modrinth works without a key — use it to confirm the extension itself is fine.</td></tr><tr><td>Install fails</td><td>The panel could not download the file, or the node rejected the upload. Check <code>storage/logs</code> and Blueprint&#39;s debug log at <code>.blueprint/extensions/blueprint/private/debug/logs.txt</code>.</td></tr><tr><td>Search 500s with custom API clients</td><td>Upgrade to ≥ 1.0.3 — older builds 500&#39;d when optional query params were omitted.</td></tr></tbody></table><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p><strong>Blueprint:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueplugininstaller</span></span></code></pre></div><p><strong>Standalone:</strong> reverse the steps in <code>standalone/INSTALLATION.md</code> (remove the symlinks, copied files, registration entries, and the <code>routes.ts</code> lines, then rebuild the frontend and clear caches).</p>`,19)])])}const g=t(a,[["render",o]]);export{h as __pageData,g as default};
